57	+/* ===== Lái xe: hình chiếc VinFast VF 3 trong cảnh (D-034) =====
58	+   - drCarLoad(): import() động GLTFLoader, nạp public/car/vf3.glb một lần, nhớ đệm. Lỗi bất kỳ hoặc quá model.timeoutMs → console.warn, null; promise không bao giờ bị từ chối.
59	+     Nguồn được chuẩn hóa một lần: lớp 1 (không vào phản chiếu nước), không đổ / nhận bóng; hai vật liệu đèn vá bằng onBeforeCompile (đọc shared.uNight, không PointLight);
60	+     chờ drCarSetWarm (compileAsync theo cảnh chính, ≤ model.warmMs) rồi mới trả nguồn.
61	+   - Đèn: lamp_head có emissive map của nguồn, nhân hệ số theo uNight. lamp_tail không có: phát sáng = màu cơ bản (cả logo trong ảnh dán) nhân hệ số.
62	+     Đèn phanh = bản vật liệu thứ hai cùng program (cùng customProgramCacheKey, chỉ khác uniform uBrake): đổi tham chiếu vật liệu của lưới đèn hậu, không biên dịch lại.
63	+   - DrCar: group có ngay với hình tạm (một Mesh gộp hộp bo + bốn trụ bánh, màu theo slot) và tấm bóng mờ dưới gầm; nạp xong thì đổi sang bản sao `body` của mô hình
64	+     (5 primitive = 5 lệnh vẽ, vật liệu `paint` nhân bản riêng để đặt màu slot). Bốn bánh KHÔNG thuộc group của xe: nằm trong drWheels, mỗi vật liệu của lưới bánh một
65	+     InstancedMesh dùng chung cho mọi xe (3 lệnh vẽ tổng cộng), mỗi xe giữ 4 chỗ liên tiếp. drWheels.group phải nằm trong cảnh (drCars.group chứa sẵn).
66	+     Lệnh vẽ: hình tạm 2 / xe; mô hình thật 5 thân + 1 bóng = 6 / xe, cộng 3 lệnh bánh chung.
67	+   - Quy ước hướng: yaw 0 = mũi +X; steer > 0 rẽ trái (cùng chiều yaw); wheel = góc lăn bánh trái (rad, tăng khi xe tiến). Mô hình: mũi +X, Y lên, đáy lốp y = 0, gốc giữa hai trục.
68	+     Bánh phải dùng chung lưới với bánh trái nên nút xoay 180 độ quanh Y: dấu quay quanh Z cục bộ lấy theo hướng Z cục bộ của bánh trong thế giới.
69	+   Không cấp phát mỗi khung. docs/superpowers/specs/2026-11-12-lai-xe-oto-design.md */
70	+import * as THREE from 'three';
71	+import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
72	+import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
73	+import { CONFIG } from '../../config';
74	+import { shared } from '../../core/shared';
75	+import { multiParams } from '../multi/params';
76	+
77	+const M = CONFIG.drive.model, CAR = CONFIG.drive.car;
78	+const WHEELS = ['wheel_fl', 'wheel_fr', 'wheel_rl', 'wheel_rr'];   // hai bánh đầu là bánh trước
79	+const CAP = (multiParams.slots + 1) * 4;                           // chỗ bánh: 6 xe × 4
80	+
81	+export interface DrPlace { x: number; y: number; z: number; yaw: number; pitch: number; steer: number; wheel: number; braking: boolean }
82	+
83	+/* ===== Vật liệu đèn: vá phát sáng theo uNight, hệ số `night`; uBrake > phát sáng nền thì thay bằng uBrake ===== */
84	+function drLampPatch(m: THREE.MeshStandardMaterial, key: string, night: number, brake: number): void {
85	+  const ub = { value: brake };
86	+  m.onBeforeCompile = (s) => {
87	+    s.uniforms.uNight = shared.uNight;
88	+    s.uniforms.uBrake = ub;
89	+    s.fragmentShader = 'uniform float uNight;\nuniform float uBrake;\n' + s.fragmentShader.replace('#include <emissivemap_fragment>',
90	+      `#include <emissivemap_fragment>\ntotalEmissiveRadiance *= max( clamp( uNight, 0.0, 1.0 ) * ${night.toFixed(3)}, uBrake );`);
91	+  };
92	+  m.customProgramCacheKey = () => key;
93	+  m.userData.lampBrake = brake;
94	+}
95	+
96	+export interface DrSource {
97	+  scene: THREE.Object3D;                       // cảnh gốc (không thêm vào cảnh; chỉ để sao chép)
98	+  body: THREE.Object3D;                        // nút body
99	+  paint: THREE.MeshStandardMaterial;           // vật liệu sơn gốc (mỗi xe nhân bản)
100	+  tail: THREE.Material; tailBrake: THREE.Material;
101	+  wheels: { pos: THREE.Vector3; quat: THREE.Quaternion; sign: number }[];   // vị trí, xoay nghỉ, dấu quay quanh Z cục bộ (4 bánh theo WHEELS)
102	+  wheelMeshes: THREE.Mesh[];                   // các lưới của wheel_fl (mỗi vật liệu một lưới)
103	+}
104	+
105	+/* Chuẩn hóa cảnh đã nạp thành nguồn dùng chung. Thiếu nút / vật liệu thì ném lỗi (drCarLoad bắt, trả null) */
106	+export function drCarSource(scene: THREE.Object3D): DrSource {
107	+  scene.updateMatrixWorld(true);
108	+  const body = scene.getObjectByName('body');
109	+  if (!body) throw new Error('thiếu nút body');
110	+  let paint: THREE.MeshStandardMaterial | null = null, head: THREE.MeshStandardMaterial | null = null, tail: THREE.MeshStandardMaterial | null = null;
111	+  scene.traverse((o) => {
112	+    o.layers.set(1);
113	+    const me = o as THREE.Mesh;
114	+    if (!me.isMesh) return;
115	+    me.castShadow = false; me.receiveShadow = false;
116	+    const mat = me.material as THREE.MeshStandardMaterial;
117	+    if (mat.name === 'paint') paint = mat;
118	+    else if (mat.name === 'lamp_head') head = mat;
119	+    else if (mat.name === 'lamp_tail') tail = mat;
120	+  });
121	+  if (!paint || !head || !tail) throw new Error('thiếu vật liệu paint / lamp_head / lamp_tail');
122	+  const h = head as THREE.MeshStandardMaterial, t = tail as THREE.MeshStandardMaterial;
123	+  drLampPatch(h, 'drLampHead', M.headNight, 0);
124	+  t.emissive.set(0xffffff); t.emissiveMap = t.map; t.emissiveIntensity = 1;   // không emissive map: lấy chính ảnh màu cơ bản
125	+  drLampPatch(t, 'drLampTail', M.tailNight, 0);
126	+  const tb = t.clone(); drLampPatch(tb, 'drLampTail', M.tailNight, M.tailBrake);   // cùng khóa program: chỉ khác uniform
127	+  const wheels: DrSource['wheels'] = [], z = new THREE.Vector3();
128	+  for (const n of WHEELS) {
129	+    const w = scene.getObjectByName(n);
130	+    if (!w) throw new Error(`thiếu nút ${n}`);
131	+    z.set(0, 0, 1).applyQuaternion(w.quaternion);
132	+    wheels.push({ pos: w.position.clone(), quat: w.quaternion.clone(), sign: z.z > 0 ? -1 : 1 });   // bánh tiến: quanh +Z thế giới góc âm
133	+  }
134	+  const wheelMeshes: THREE.Mesh[] = [];
135	+  scene.getObjectByName(WHEELS[0]).traverse((o) => { if ((o as THREE.Mesh).isMesh) wheelMeshes.push(o as THREE.Mesh); });
136	+  if (!wheelMeshes.length) throw new Error('bánh không có lưới');
137	+  return { scene, body, paint: paint as THREE.MeshStandardMaterial, tail: t, tailBrake: tb, wheels, wheelMeshes };
138	+}
139	+
140	+/* ===== Nạp (nhớ đệm) ===== */
141	+let warm: ((o: THREE.Object3D) => Promise<unknown>) | null = null;
142	+export function drCarSetWarm(fn: ((o: THREE.Object3D) => Promise<unknown>) | null): void { warm = fn; }
143	+async function drCarWarm(o: THREE.Object3D): Promise<void> {
144	+  if (!warm) return;
145	+  let timer = 0;
146	+  try { await Promise.race([warm(o), new Promise<void>((r) => { timer = setTimeout(r, M.warmMs) as unknown as number; })]); }
147	+  catch { /* biên dịch trước lỗi: lần vẽ đầu tự biên dịch */ }
148	+  finally { clearTimeout(timer); }
149	+}
150	+
151	+async function drCarDefaultLoader(): Promise<THREE.Object3D> {
152	+  const { GLTFLoader } = await import('three/addons/loaders/GLTFLoader.js');
153	+  const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + M.url);
154	+  return gltf.scene;
155	+}
156	+
157	+let loader: () => Promise<THREE.Object3D> = drCarDefaultLoader;
158	+let cache: Promise<THREE.Object3D | null> | null = null;
159	+let sources = new WeakMap<THREE.Object3D, DrSource>();
160	+let gen = 0;
161	+
162	+/* Nạp mô hình xe. Không bao giờ ném / từ chối: lỗi hoặc quá model.timeoutMs → warn một lần, null */
163	+export function drCarLoad(): Promise<THREE.Object3D | null> {
164	+  if (cache) return cache;
165	+  const work = (async () => {
166	+    const scene = await loader();
167	+    const src = drCarSource(scene);
168	+    sources.set(scene, src);
169	+    await drCarWarm(scene);
170	+    return scene as THREE.Object3D | null;
171	+  })();
172	+  let timer = 0;
173	+  const p = Promise.race([work, new Promise<null>((r) => { timer = setTimeout(() => r(null), M.timeoutMs) as unknown as number; })])
174	+    .catch((e) => { console.warn('Lái xe: không nạp được mô hình xe, dùng hình tạm', e); return null; })
175	+    .finally(() => clearTimeout(timer));
176	+  work.catch(() => { /* lỗi đã xử lý ở nhánh race; chặn cảnh báo promise bị bỏ */ });
177	+  cache = p;
178	+  return p;
179	+}
180	+
181	+/* Cho test: thay bộ nạp (null: mặc định), xóa đệm, bỏ bánh dùng chung */
182	+export function drCarSetLoader(fn: (() => Promise<THREE.Object3D>) | null): void {
183	+  loader = fn || drCarDefaultLoader; cache = null; sources = new WeakMap(); gen++;
184	+  drWheels.reset();
185	+}
186	+
187	+/* ===== Bánh dùng chung: mỗi vật liệu một InstancedMesh, CAP chỗ ===== */
188	+const A = new THREE.Matrix4(), B = new THREE.Matrix4(), Q = new THREE.Quaternion(), Q2 = new THREE.Quaternion(), UNIT = new THREE.Vector3(1, 1, 1), ZERO = new THREE.Matrix4().makeScale(0, 0, 0);
189	+const AXY = new THREE.Vector3(0, 1, 0), AXZ = new THREE.Vector3(0, 0, 1);
190	+
191	+class DrWheelPool {
192	+  readonly group = new THREE.Group();
193	+  meshes: THREE.InstancedMesh[] = [];
194	+  private src: DrSource | null = null;
195	+  private used: boolean[] = new Array(CAP / 4).fill(false);
196	+  constructor() { this.group.name = 'drive-wheels'; this.group.visible = false; }
197	+  /* Dựng 3 InstancedMesh từ lưới bánh của nguồn (một lần cho mỗi nguồn) */
198	+  setup(src: DrSource): void {
199	+    if (this.src === src) return;
200	+    this.reset();
201	+    this.src = src;
202	+    for (const m of src.wheelMeshes) {
203	+      const im = new THREE.InstancedMesh(m.geometry, m.material, CAP);
204	+      im.name = 'drive-wheels-' + (Array.isArray(m.material) ? '' : m.material.name);
205	+      im.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
206	+      for (let i = 0; i < CAP; i++) im.setMatrixAt(i, ZERO);
207	+      im.count = 0; im.frustumCulled = false; im.castShadow = false; im.receiveShadow = false; im.layers.set(1);
208	+      this.meshes.push(im); this.group.add(im);
209	+    }
210	+  }
211	+  /* Chỗ trống đầu tiên (chỉ số instance đầu của 4 bánh), -1 nếu hết */
212	+  acquire(): number {
213	+    const k = this.used.indexOf(false);
214	+    if (k < 0) return -1;
215	+    this.used[k] = true;
216	+    this.group.visible = true;
217	+    this.fit();
218	+    return k * 4;
219	+  }
220	+  release(base: number): void {
221	+    if (base < 0) return;
222	+    this.used[base / 4] = false;
223	+    for (const im of this.meshes) { for (let i = 0; i < 4; i++) im.setMatrixAt(base + i, ZERO); im.instanceMatrix.needsUpdate = true; }
224	+    this.fit();
225	+  }
226	+  private fit(): void {
227	+    const top = this.used.lastIndexOf(true);
228	+    for (const im of this.meshes) im.count = (top + 1) * 4;
229	+    this.group.visible = top >= 0;
230	+  }
231	+  /* Ma trận 4 bánh của xe có ma trận thế giới `car` */
232	+  set(base: number, car: THREE.Matrix4, steer: number, wheel: number): void {
233	+    const w = this.src!.wheels;
234	+    for (let i = 0; i < 4; i++) {
235	+      const d = w[i];
236	+      Q.setFromAxisAngle(AXY, i < 2 ? steer : 0).multiply(d.quat).multiply(Q2.setFromAxisAngle(AXZ, d.sign * wheel));   // lái (chỉ bánh trước), xoay nghỉ của nút, rồi lăn quanh Z cục bộ
237	+      A.compose(d.pos, Q, UNIT);
238	+      B.multiplyMatrices(car, A);
239	+      for (const im of this.meshes) im.setMatrixAt(base + i, B);
240	+    }
241	+    for (const im of this.meshes) im.instanceMatrix.needsUpdate = true;
242	+  }
243	+  reset(): void {
244	+    for (const im of this.meshes) { this.group.remove(im); im.dispose(); }
245	+    this.meshes = []; this.src = null; this.used.fill(false); this.group.visible = false;
246	+  }
247	+}
248	+const B3 = new THREE.Quaternion();
249	+export const drWheels = new DrWheelPool();
250	+
251	+/* ===== Hình tạm và tấm bóng dùng chung ===== */
252	+let tempMat: THREE.MeshStandardMaterial | null = null, shadowMat: THREE.MeshBasicMaterial | null = null, shadowGeo: THREE.PlaneGeometry | null = null, shadowTex: THREE.DataTexture | null = null;
253	+
254	+function drTempGeometry(color: string): THREE.BufferGeometry {
255	+  const L = CAR.length, W = CAR.width, H = CAR.height - CAR.clearance, r = CAR.wheelDia / 2, ww = M.temp.wheelWidth;
256	+  const col = new THREE.Color(color), dark = new THREE.Color(0x15151a);
257	+  const paint = (g: THREE.BufferGeometry, c: THREE.Color): THREE.BufferGeometry => {
258	+    const n = g.attributes.position.count, a = new Float32Array(n * 3);
259	+    for (let i = 0; i < n; i++) { a[i * 3] = c.r; a[i * 3 + 1] = c.g; a[i * 3 + 2] = c.b; }
260	+    g.setAttribute('color', new THREE.BufferAttribute(a, 3));
261	+    return g;
262	+  };
263	+  const parts: THREE.BufferGeometry[] = [paint(new RoundedBoxGeometry(L, H, W, 2, 0.12).translate(0, CAR.clearance + H / 2, 0), col)];
264	+  const ax = CAR.wheelbase / 2, az = W / 2 - ww / 2;
265	+  for (const sx of [1, -1]) for (const sz of [1, -1]) {
266	+    parts.push(paint(new THREE.CylinderGeometry(r, r, ww, 12).rotateX(Math.PI / 2).translate(sx * ax, r, sz * az), dark));
267	+  }
268	+  const g = mergeGeometries(parts.map((p) => p.index ? p.toNonIndexed() : p))!;   // 1 Mesh gộp
269	+  for (const p of parts) p.dispose();
270	+  return g;
271	+}
272	+
273	+function drShadowShared(): void {
274	+  if (shadowMat) return;
275	+  const n = 32, d = new Uint8Array(n * n * 4);
276	+  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
277	+    const u = (x + 0.5) / n * 2 - 1, v = (y + 0.5) / n * 2 - 1;
278	+    const e = Math.max(Math.abs(u), Math.abs(v)), a = e >= 1 ? 0 : 1 - e * e * e * e;   // mép mềm hình vuông bo
279	+    d[(y * n + x) * 4 + 3] = Math.round(255 * a);
