400	+export const drCars = {
401	+  group,
402	+  sync(peers: { slot: number }[]): void {
403	+    const want = new Set<number>();
404	+    for (const p of peers) {
405	+      want.add(p.slot);
406	+      if (cars.has(p.slot)) continue;
407	+      const c = new DrCar(multiParams.colors[((p.slot % multiParams.colors.length) + multiParams.colors.length) % multiParams.colors.length]);
408	+      cars.set(p.slot, c); group.add(c.group);
409	+    }
410	+    for (const [s, c] of cars) if (!want.has(s)) { c.dispose(); cars.delete(s); }
411	+  },
412	+  place(slot: number, p: DrPlace): void { cars.get(slot)?.place(p); },
413	+  /* Vị trí xe của slot vào out; false nếu không có xe */
414	+  pos(slot: number, out: THREE.Vector3): boolean {
415	+    const c = cars.get(slot);
416	+    if (!c) return false;
417	+    out.copy(c.group.position);
418	+    return true;
419	+  },
420	+  clear(): void { for (const c of cars.values()) c.dispose(); cars.clear(); },
421	+  /* Gỡ hết, kể cả vật liệu / bánh dùng chung (rời chế độ hẳn) */
422	+  dispose(): void { this.clear(); drCarDisposeShared(); }
